const { Client } = require("@hubspot/api-client");

const hubspotClient = new Client({ accessToken: $vars.hs_token_3 });

const trip_options = $("format_options").all()[0].json;
const api_responses = [];
for (let data in trip_options) {
  const PropertyUpdate = {
    groupName: "company_activity",
    hidden: false,
    options: trip_options[data].options,
    displayOrder: -1,
    description: trip_options[data].description,
    label: trip_options[data].label,
    type: "enumeration",
    fieldType: "select",
    formField: true,
  };

  const objectType = "company";
  const propertyName = trip_options[data].property_name;

  const apiResponse = await hubspotClient.crm.properties.coreApi.update(
    objectType,
    propertyName,
    PropertyUpdate,
  );
  api_responses.push(apiResponse);
}

return api_responses;

//Generate values for dropdown
const upcoming_trips = $("get_upcoming_trips").all();
const trip_options = []
for(let trip of upcoming_trips){
  trip_options.push({
    hidden: false,
      displayOrder: 0,
      description: "",
      label: trip.json.trip_name,
      value: trip.json.trip_id,
  })
}


return {trip_options:trip_options};

function merge_options(new_options, current_options) {
  const mergedArray = current_options.map((item2, index) => {
    // Check if the value is in new_options
    const itemInArray1 = new_options.find(
      (item1) => item1.value === item2.value,
    );

    if (itemInArray1) {
      // If item exists in new_options, merge and keep 'hidden' as false because it will appear on the form
      return { ...itemInArray1, displayOrder: index }; // Copy from new_options and add displayOrder
    } else {
      // If item doesn't exist in new_options, set 'hidden' to true because it need to be hidden in the form
      return { ...item2, hidden: true, displayOrder: index }; // Set hidden to true and add displayOrder
    }
  });

  // Add the items from new_options that were not in current_options, with appropriate displayOrder
  new_options.forEach((item1, index) => {
    if (!mergedArray.some((item) => item.value === item1.value)) {
      mergedArray.push({ ...item1, displayOrder: mergedArray.length });
    }
  });

  return mergedArray;
}

const current_values = $("get_current_values").all()[0].json;
const new_options = $("generate_values").all()[0].json;

const options = merge_options(new_options.trip_options, current_values.trips);
return {
  data: {
    options: options,
    label: "SLT Destination, Date and Season",
    description: "Dropdown menu with upcoming MEDLIFE Trips",
    property_name: "slt_destination__date_and_season",
  },
};

